#!/usr/bin/env bash
# GENERATED by plugin-cursor/scripts/compose.sh — edit plugin/ then re-compose

# --- synaptory: resolve Python interpreter (magic-number safe) ---
# shellcheck source=lib/resolve-python.sh
. "$(dirname "${BASH_SOURCE[0]}")/lib/resolve-python.sh"
: "${SYNAPTORY_PYTHON:?synaptory requires a working Python 3 interpreter (set SYNAPTORY_PYTHON to override)}"
# -------------------------------------------------------------
# Copyright (c) 2024-2026 H3Tech Inc. All rights reserved. PROPRIETARY.
# Hook: PreCompact
# Purpose: Before context window compaction, re-inject key pipeline artifacts
# so they survive compaction and the agent can resume without losing state.

_HOOK_ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
# shellcheck source=lib/resolve-python.sh
source "${_HOOK_ROOT}/hooks/lib/resolve-python.sh"
_py="${SYNAPTORY_PYTHON:-python3}"

SUITE_DIR="${CLAUDE_PROJECT_DIR}/.synaptory"

# Only fire if the suite directory exists
if [ ! -d "$SUITE_DIR" ]; then
  exit 0
fi

CONTEXT=""

# Part 0: Compacted behavioral rules (survive compaction)
# Full rules load on SessionStart via synaptory-load-rules.sh (~5K tokens).
# This condensed version (~500 tokens) preserves essential directives
# through context compaction events.
COMPACTED_RULES="${PLUGIN_ROOT}/hooks/data/compacted-rules.md"
if [ -f "$COMPACTED_RULES" ]; then
  RULES_CONTENT=$(cat "$COMPACTED_RULES" 2>/dev/null)
  if [ -n "$RULES_CONTENT" ]; then
    CONTEXT="${CONTEXT}${RULES_CONTENT}

---
"
  fi
fi

# Part 1: Settings (first 50 lines)
if [ -f "$SUITE_DIR/.orchestrator/settings.md" ]; then
  SETTINGS=$(head -50 "$SUITE_DIR/.orchestrator/settings.md" 2>/dev/null)
  CONTEXT="${CONTEXT}## Pipeline Settings
${SETTINGS}

---
"
fi

# Part 2: Most recent 3 receipts (first 20 lines each)
RECEIPTS_DIR="$SUITE_DIR/.orchestrator/receipts"
if [ -d "$RECEIPTS_DIR" ]; then
  RECENT_RECEIPTS=$(ls -t "$RECEIPTS_DIR"/*.json 2>/dev/null | head -3)
  if [ -n "$RECENT_RECEIPTS" ]; then
    CONTEXT="${CONTEXT}## Recent Agent Completions
"
    while IFS= read -r receipt; do
      RECEIPT_NAME=$(basename "$receipt")
      RECEIPT_CONTENT=$(head -20 "$receipt" 2>/dev/null)
      CONTEXT="${CONTEXT}### ${RECEIPT_NAME}
${RECEIPT_CONTENT}

"
    done <<< "$RECENT_RECEIPTS"
    CONTEXT="${CONTEXT}---
"
  fi
fi

# Part 3: BRD summary (first 30 lines)
BRD_FILE=$(find "$SUITE_DIR/project-owner/BRD" -name "*.md" 2>/dev/null | head -1)
if [ -n "$BRD_FILE" ] && [ -f "$BRD_FILE" ]; then
  BRD_SUMMARY=$(head -30 "$BRD_FILE" 2>/dev/null)
  CONTEXT="${CONTEXT}## BRD Summary
${BRD_SUMMARY}

---
"
fi

# Part 4: ADR titles
ADR_TITLES=$(grep -r "^# " "$SUITE_DIR" --include="ADR-*.md" 2>/dev/null | sed 's|.*:# |• |')
if [ -n "$ADR_TITLES" ]; then
  CONTEXT="${CONTEXT}## Architecture Decisions
${ADR_TITLES}
"
fi

# Part 5: Context packages (brownfield knowledge — summaries for compaction survival)
CONTEXT_PKG_DIR="$SUITE_DIR/.orchestrator/context-packages"
if [ -d "$CONTEXT_PKG_DIR" ]; then
  PKG_COUNT=$(find "$CONTEXT_PKG_DIR" -name "*.md" 2>/dev/null | wc -l | tr -d ' ')
  if [ "$PKG_COUNT" -gt 0 ]; then
    CONTEXT="${CONTEXT}## Context Packages (${PKG_COUNT} packages)
"
    # Health assessment summary (first 30 lines)
    if [ -f "$CONTEXT_PKG_DIR/health-assessment.md" ]; then
      HA_SUMMARY=$(head -30 "$CONTEXT_PKG_DIR/health-assessment.md" 2>/dev/null)
      CONTEXT="${CONTEXT}### Health Assessment
${HA_SUMMARY}

"
    fi

    # Business rules inventory summary (first 30 lines)
    if [ -f "$CONTEXT_PKG_DIR/business-rules-inventory.md" ]; then
      BR_SUMMARY=$(head -30 "$CONTEXT_PKG_DIR/business-rules-inventory.md" 2>/dev/null)
      CONTEXT="${CONTEXT}### Business Rules (summary)
${BR_SUMMARY}

"
    fi

    # Risk register summary (first 30 lines)
    if [ -f "$CONTEXT_PKG_DIR/risk-register.md" ]; then
      RR_SUMMARY=$(head -30 "$CONTEXT_PKG_DIR/risk-register.md" 2>/dev/null)
      CONTEXT="${CONTEXT}### Risk Register (summary)
${RR_SUMMARY}

"
    fi

    CONTEXT="${CONTEXT}---
"
  fi
fi

if [ -z "$CONTEXT" ]; then
  exit 0
fi

# Part 6: Update CLAUDE.md sentinel (pipeline state snapshot for post-compaction recovery)
# Multi-spec aware (docs/multi-spec-design.md §5.2): the state-derived
# fields come from the rollup writer, then settings-derived fields are
# overlaid via --sentinel-write merge.
# Run in background to avoid blocking compaction. Failures are silent.
(
  UPDATER="${PLUGIN_ROOT}/hooks/lib/update_claude_md.py"
  SETTINGS_FILE="$SUITE_DIR/.orchestrator/settings.md"

  # 1) Re-render the state section (handles v2 and v3 layouts).
  "$_py" "$UPDATER" "$CLAUDE_PROJECT_DIR" --rollup-sentinel >/dev/null 2>&1 || true

  # 2) Overlay engagement / parallelism / quality / tracker from settings.md.
  if [ -f "$SETTINGS_FILE" ]; then
    "$_py" - "$CLAUDE_PROJECT_DIR" "$SETTINGS_FILE" "$UPDATER" <<'PYEOF'
import json, os, subprocess, sys
project_dir, settings_file, updater = sys.argv[1], sys.argv[2], sys.argv[3]
overlay = {}
try:
    with open(settings_file) as f:
        for line in f:
            line = line.strip()
            for key in ("engagement", "parallelism", "quality", "tracker"):
                if line.lower().startswith(key + ":"):
                    overlay[key] = line.split(":", 1)[1].strip().lower()
                    break
except Exception:
    pass
if overlay:
    subprocess.run(
        [os.environ.get("SYNAPTORY_PYTHON", "python3"), updater, project_dir, "--sentinel-write"],
        input=json.dumps(overlay).encode(),
        capture_output=True,
    )
PYEOF
  fi
) 2>/dev/null &

# Output structured JSON
printf '%s' "$CONTEXT" | SYNAPTORY_HOOK_LIB="${_HOOK_ROOT}/hooks/lib" "$_py" -c "
import sys, os
sys.path.insert(0, os.environ['SYNAPTORY_HOOK_LIB'])
from hook_io import emit
emit('PreCompact', additional_context=sys.stdin.read())
" 2>/dev/null || exit 0

exit 0
